{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Not Enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The S3 bucket 'financials' does not have server access logging enabled, which is critical for auditing and security monitoring of financial data."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Public Access Block Configuration Missing",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The bucket lacks an explicit aws_s3_bucket_public_access_block resource. While the ACL is private, explicit public access blocking is required to prevent accidental exposure via policy or future configuration changes."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_logging" "financials_logging" {
  bucket = aws_s3_bucket.financials.id

  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "log/"
}

# Note: A separate log bucket must exist. Assuming a standard pattern for remediation.
resource "aws_s3_bucket" "log_bucket" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_public_access_block" "financials_pab" {
  bucket = aws_s3_bucket.financials.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Added `aws_s3_bucket_public_access_block` to explicitly deny public access. Added `aws_s3_bucket_logging` to enable access logging, including the creation of a dedicated `log_bucket` with appropriate ACLs to serve as the destination for logs."
}
